<?php
/** Topic compose/edit form; protected ownership is never submitted as fields. */
use yii\helpers\Html;
$this->title=$model->isNewRecord?'发起讨论':'编辑讨论';
?>
<a class="back-link" href="/forum">← 球迷论坛</a><section class="page-heading"><h1><?= e($this->title) ?></h1></section>
<form class="form-panel prose" method="post"><?= csrf_field() ?><?= Html::errorSummary($model,['class'=>'form-errors']) ?><label>标题<input name="title" value="<?= e($model->title) ?>" minlength="3" maxlength="160" required placeholder="一个清楚、有内容的讨论标题"></label><div class="form-grid"><label>板块<select name="category_id" required><?php foreach($categories as $c): ?><option value="<?= (int)$c->id ?>" <?= $model->category_id==$c->id?'selected':'' ?>><?= e($c->name) ?></option><?php endforeach ?></select></label><label>关联主队<select data-team-select name="team_id"><option value="">不限球队</option><?php foreach($teams as $t): ?><option data-flag="<?= e(\app\services\TeamUi::url($t)) ?>" value="<?= (int)$t->id ?>" <?= $model->team_id==$t->id?'selected':'' ?>><?= e($t->name) ?></option><?php endforeach ?></select></label></div><label>关联比赛（可选）<select data-team-select name="match_id"><option value="">不关联比赛</option><?php foreach($matches as $m): ?><option data-flag="<?= e(\app\services\TeamUi::url($m->homeTeam)) ?>" data-away-flag="<?= e(\app\services\TeamUi::url($m->awayTeam)) ?>" value="<?= (int)$m->id ?>" <?= $model->match_id==$m->id?'selected':'' ?>>#<?= (int)$m->id ?> <?= e($m->homeTeam?->name) ?> / <?= e($m->awayTeam?->name) ?> · <?= e($m->stage) ?></option><?php endforeach ?></select></label><label>正文<textarea name="body" rows="12" minlength="5" maxlength="20000" required placeholder="写下你的观点、分析或观赛故事。支持纯文本，引用信息请附来源。 "><?= e($model->body) ?></textarea></label><button class="button">发布讨论 ↗</button></form>
